/* GOP linear framebuffer console: 8x16 bitmap font, 16-colour-ish text. */

#include <mcube/kernel.h>
#include <mcube/io.h>
#include <mcube/mm.h>

#define FONT_W 8
#define FONT_H 16

/* Generated by tools/gen_font.py (DejaVu Sans Mono, free licence).
 * 256 glyphs x 16 bytes, one bit per pixel, MSB = leftmost column. */
extern const u8 mc_font8x16[256][FONT_H];

static struct {
    u8 *base;
    u32 width, height, pitch;
    u32 format;
    u32 fg, bg;
    u32 cols, rows;
    u32 cx, cy;
    int ready;
} g_fb;

static u32 rgb_to_pixel(u8 r, u8 g, u8 b) {
    switch (g_fb.format) {
    case BOOT_PIXEL_BGRA8888:
        return ((u32)0xFF << 24) | ((u32)r << 16) | ((u32)g << 8) | b;
    case BOOT_PIXEL_RGBA8888:
    default:
        return ((u32)0xFF << 24) | ((u32)b << 16) | ((u32)g << 8) | r;
    }
}

static inline void put_pixel(u32 x, u32 y, u32 color) {
    if (x >= g_fb.width || y >= g_fb.height) return;
    *(u32 *)(g_fb.base + (u64)y * g_fb.pitch + (u64)x * 4) = color;
}

static void fill_rect(u32 x, u32 y, u32 w, u32 h, u32 color) {
    for (u32 row = 0; row < h; row++) {
        if (y + row >= g_fb.height) break;
        u32 *line = (u32 *)(g_fb.base + (u64)(y + row) * g_fb.pitch) + x;
        for (u32 col = 0; col < w && x + col < g_fb.width; col++) line[col] = color;
    }
}

static void scroll_if_needed(void) {
    if (g_fb.cy < g_fb.rows) return;
    u32 line_bytes = g_fb.pitch;
    u64 scroll_bytes = (u64)FONT_H * line_bytes;
    memmove(g_fb.base, g_fb.base + scroll_bytes,
            (u64)g_fb.height * line_bytes - scroll_bytes);
    fill_rect(0, (g_fb.rows - 1) * FONT_H, g_fb.width, FONT_H, g_fb.bg);
    g_fb.cy = g_fb.rows - 1;
}

void fb_init(const boot_info_t *bi) {
    memset(&g_fb, 0, sizeof(g_fb));
    if (!bi || !bi->fb_base || bi->fb_width == 0 || bi->fb_height == 0) return;

    g_fb.base = (u8 *)phys_to_virt(bi->fb_base);
    g_fb.width = bi->fb_width;
    g_fb.height = bi->fb_height;
    g_fb.pitch = bi->fb_pitch ? bi->fb_pitch : bi->fb_width * 4;
    g_fb.format = bi->fb_format;
    g_fb.fg = rgb_to_pixel(0xE6, 0xE9, 0xF0);
    g_fb.bg = rgb_to_pixel(0x0B, 0x0D, 0x14);
    g_fb.cols = g_fb.width / FONT_W;
    g_fb.rows = g_fb.height / FONT_H;
    g_fb.cx = g_fb.cy = 0;
    g_fb.ready = 1;
    fb_clear();
}

void fb_clear(void) {
    if (!g_fb.ready) return;
    fill_rect(0, 0, g_fb.width, g_fb.height, g_fb.bg);
    g_fb.cx = g_fb.cy = 0;
}

static void draw_glyph(u32 cx, u32 cy, u8 ch) {
    const u8 *glyph = mc_font8x16[ch];
    u32 px = cx * FONT_W;
    u32 py = cy * FONT_H;
    for (u32 row = 0; row < FONT_H; row++) {
        u8 bits = glyph[row];
        for (u32 col = 0; col < FONT_W; col++) {
            u32 color = (bits & (0x80 >> col)) ? g_fb.fg : g_fb.bg;
            put_pixel(px + col, py + row, color);
        }
    }
}

void fb_putc(char c) {
    if (!g_fb.ready) return;

    switch (c) {
    case '\n':
        g_fb.cx = 0;
        g_fb.cy++;
        scroll_if_needed();
        return;
    case '\r':
        g_fb.cx = 0;
        return;
    case '\t': {
        u32 next = (g_fb.cx + 4) & ~3u;
        while (g_fb.cx < next) fb_putc(' ');
        return;
    }
    case '\b':
        if (g_fb.cx > 0) g_fb.cx--;
        draw_glyph(g_fb.cx, g_fb.cy, ' ');
        return;
    default:
        break;
    }

    if ((u8)c < 32) return;
    draw_glyph(g_fb.cx, g_fb.cy, (u8)c);
    g_fb.cx++;
    if (g_fb.cx >= g_fb.cols) {
        g_fb.cx = 0;
        g_fb.cy++;
        scroll_if_needed();
    }
}

void fb_write(const char *s) {
    while (*s) fb_putc(*s++);
}

void fb_get_size(u32 *cols, u32 *rows) {
    if (cols) *cols = g_fb.ready ? g_fb.cols : 0;
    if (rows) *rows = g_fb.ready ? g_fb.rows : 0;
}

/* Used by the early animation/logo code in later milestones. */
void fb_fill_rect(u32 x, u32 y, u32 w, u32 h, u32 rgb) {
    if (!g_fb.ready) return;
    fill_rect(x, y, w, h, rgb_to_pixel((u8)(rgb >> 16), (u8)(rgb >> 8), (u8)rgb));
}
